var REDIS_STATUS_MSG_KEY = process.env.NODE_ENV === "production" ? "sigilos:discord_status_message_id_prod" : "sigilos:discord_status_message_id_beta";
async function sendGlobalStatusPing(isTestRequest = false, mode, isLite, targetChannelId) {
  if (isTestRequest) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Acc\xE8s refus\xE9 : Super-admin requis");
  }
  try {
    const config = await db.platformConfig.findUnique({
      where: { id: "singleton" },
      select: {
        serviceStatusChannelId: true,
        statusIsLite: true,
        statusMode: true,
        statusMention: true
      }
    });
    const channelId = targetChannelId || config?.serviceStatusChannelId;
    if (!channelId) {
      return { success: false, error: "Salon d'\xE9tat des services non configur\xE9." };
    }
    const effectiveMode = mode || config?.statusMode || "living";
    const effectiveLite = isLite !== void 0 ? isLite : config?.statusIsLite || false;
    const startDb = performance.now();
    await db.$queryRaw`SELECT 1`;
    const dbLatency = Math.round(performance.now() - startDb);
    const isDbOk = dbLatency < 500;
    let isRedisOk = false;
    let redisLatency = 0;
    try {
      const startRedis = performance.now();
      const pong = await redis.ping();
      redisLatency = Math.round(performance.now() - startRedis);
      isRedisOk = pong === "PONG";
    } catch (e2) {
      logger.error("[Status Ping] Redis error:", e2);
    }
    const isBeta2 = process.env.NEXT_PUBLIC_APP_URL?.includes("beta") || process.env.NODE_ENV !== "production";
    const envName = isBeta2 ? "Beta / Test" : "Production";
    const uptimeSeconds = process.uptime();
    const uptimeDays = Math.floor(uptimeSeconds / (24 * 3600));
    const uptimeHours = Math.floor(uptimeSeconds % (24 * 3600) / 3600);
    const uptimeFormatted = uptimeDays > 0 ? `${uptimeDays}j ${uptimeHours}h` : `${uptimeHours}h ${Math.floor(uptimeSeconds % 3600 / 60)}m`;
    const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr";
    const statusUrl = `${appUrl}/status`;
    const systemStatus = isDbOk && isRedisOk ? "OPERATIONAL" : !isDbOk && !isRedisOk ? "CRITICAL" : "DEGRADED";
    const statusColor = systemStatus === "OPERATIONAL" ? 1096065 : systemStatus === "DEGRADED" ? 16096779 : 15680580;
    const fields = effectiveLite ? [
      {
        name: "Syst\xE8me",
        value: systemStatus === "OPERATIONAL" ? "\u2705 Op\xE9rationnel" : "\u26A0\uFE0F Perturb\xE9",
        inline: true
      },
      {
        name: "Environnement",
        value: `\`${envName}\``,
        inline: true
      }
    ] : [
      {
        name: "\u{1F4E1} \xC9tat des Services",
        value: systemStatus === "OPERATIONAL" ? "\u2705 Tous les syst\xE8mes sont op\xE9rationnels." : "\u26A0\uFE0F Certains services rencontrent des difficult\xE9s.",
        inline: false
      },
      {
        name: "\u{1F30D} Environnement",
        value: `\`${envName}\``,
        inline: true
      },
      {
        name: "\u{1F4E6} Version",
        value: `\`v${process.env.npm_package_version || "0.1.0"}\``,
        inline: true
      }
    ];
    const embed = {
      embedTitle: `\u{1F6F0}\uFE0F SigilOS \u2014 \xC9tat des Syst\xE8mes`,
      embedUrl: statusUrl,
      embedDescription: !effectiveLite && systemStatus !== "OPERATIONAL" ? "Nos \xE9quipes (enfin, le robot de maintenance) analysent actuellement l'incident." : void 0,
      embedColor: statusColor,
      embedThumbnail: effectiveLite ? void 0 : "https://sigilos.fr/assets/ui/logo-v2.png",
      fields,
      embedFooter: `SigilOS Status \u2022 Mise \xE0 jour auto`
    };
    const previousMessageId = await redis.get(REDIS_STATUS_MSG_KEY);
    let actionTaken = "created";
    let finalMessageId = null;
    if (effectiveMode === "living" && previousMessageId) {
      try {
        const updated = await updateChannelMessage(channelId, previousMessageId, "", embed);
        if (updated) {
          finalMessageId = previousMessageId;
          actionTaken = "updated";
        }
      } catch (e2) {
        logger.warn("[Status Ping] Update failed, sending new message", e2);
      }
    }
    if (!finalMessageId) {
      const mentionContent = config?.statusMention === "none" ? "" : config?.statusMention || "";
      finalMessageId = await sendChannelMessage(channelId, mentionContent, embed);
      if (finalMessageId && effectiveMode === "living") {
        await redis.set(REDIS_STATUS_MSG_KEY, finalMessageId, "EX", 60 * 60 * 24 * 30);
      }
    }
    return {
      success: true,
      action: actionTaken,
      messageId: finalMessageId,
      stats: {
        systemStatus,
        dbLatency,
        redisLatency,
        channelId
      }
    };
  } catch (error) {
    logger.error("[Status Action] Critical Failure:", error);
    return { success: false, error: error.message || "Erreur de connexion Discord (v\xE9rifiez l'ID du salon)" };
  }
}

