async function sendDailySummaryReport(guildId, isManual = false) {
  if (isManual) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Acc\xE8s refus\xE9");
  } else {
    const session2 = await auth();
    if (session2?.user?.id) {
      const isAdmin = await isSuperAdmin();
      if (!isAdmin) throw new Error("Acc\xE8s refus\xE9");
    }
    const today = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
    const key = `daily-report:${guildId}:${today}`;
    try {
      const claimed = await redis.set(key, "1", "EX", 86400, "NX");
      if (claimed !== "OK") {
        logger.info(`[Daily Report] D\xE9j\xE0 envoy\xE9 aujourd'hui pour ${guildId} (${today}) \u2014 skip anti-doublon.`);
        return { success: true, messageId: null, skipped: true };
      }
    } catch (e2) {
      logger.warn("[Daily Report] Redis indisponible, pas de d\xE9duplication:", e2);
    }
  }
  try {
    const lastWeek = new Date(Date.now() - 7 * 24 * 60 * 60 * 1e3);
    const [config, weeklyActiveUsers] = await Promise.all([
      db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: {
          name: true,
          systemNotifyChannelId: true,
          _count: { select: { profiles: true } }
        }
      }),
      db.userProfile.count({
        where: {
          guild: { discordGuildId: guildId },
          status: "ACTIVE",
          lastSeen: { gte: lastWeek }
        }
      })
    ]);
    if (!config?.systemNotifyChannelId) {
      return { success: false, error: "Canal de notification syst\xE8me non configur\xE9 pour cette guilde." };
    }
    const { getAppBaseUrl: getAppBaseUrl2 } = await Promise.resolve().then(() => (init_utils(), utils_exports));
    const dashboardUrl = `${getAppBaseUrl2()}/dashboard/${guildId}/admin/members`;
    const embed = {
      embedTitle: `\u{1F4CB} Rapport de guilde \u2014 ${config.name}`,
      embedUrl: dashboardUrl,
      embedDescription: `R\xE9sum\xE9 de l'activit\xE9 de la guilde sur les derni\xE8res 24 heures.
[G\xE9rer les membres et l'audit \u27A1\uFE0F](${dashboardUrl})`,
      embedColor: 1096065,
      // Emerald
      embedThumbnail: "https://sigilos.fr/assets/ui/logo-v2.png",
      fields: [
        {
          name: "\u{1F465} Membres",
          value: `Inscrits sur SigilOS: **${config._count.profiles}**`,
          inline: true
        },
        {
          name: "\u2699\uFE0F Services",
          value: "Tous les services sont op\xE9rationnels.",
          inline: true
        },
        {
          name: "\u{1F4C8} Activit\xE9 (7 jours)",
          value: `Membres actifs: **${weeklyActiveUsers}**`,
          inline: false
        }
      ],
      embedFooter: `SigilOS \u2022 Rapport du ${(/* @__PURE__ */ new Date()).toLocaleDateString("fr-FR")}`
    };
    const messageId = await sendChannelMessage(config.systemNotifyChannelId, "", embed);
    if (!messageId) {
      return { success: false, error: "\xC9chec de l'envoi sur Discord." };
    }
    return { success: true, messageId };
  } catch (error) {
    logger.error("[Daily Report] Error:", error);
    return { success: false, error: error.message || "Erreur lors de la g\xE9n\xE9ration du rapport" };
  }
}

